// src/RegisterPage.js
import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import api from "./api/apiClient";

/* Puedes reutilizar las mismas imágenes del login si quieres */
import logo from "./assets/login/logo.png";
import heroImg from "./assets/login/login-hero.png";
import sportIcon from "./assets/login/icon-deportista.png";
import adminIcon from "./assets/login/icon-admin.png";

export default function RegisterPage() {
  const navigate = useNavigate();

  const [role, setRole] = useState("deportista"); // "deportista" | "club"

  // Campos comunes
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [passwordConfirm, setPasswordConfirm] = useState("");

  // Deportista
  const [depNombre, setDepNombre] = useState("");
  const [depApellido, setDepApellido] = useState("");
  const [depDocumento, setDepDocumento] = useState("");
  const [depTelefono, setDepTelefono] = useState("");

  // Club
  const [clubNombre, setClubNombre] = useState("");
  const [clubNit, setClubNit] = useState("");
  const [clubDireccion, setClubDireccion] = useState("");
  const [clubTel1, setClubTel1] = useState("");
  const [clubTel2, setClubTel2] = useState("");
  const [clubDepartamento, setClubDepartamento] = useState("");
  const [clubCiudad, setClubCiudad] = useState("");
  const [clubDisponibilidad, setClubDisponibilidad] = useState("");
  const [clubInformacion, setClubInformacion] = useState("");

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");
  const [successMsg, setSuccessMsg] = useState("");

  const handleSubmit = async (e) => {
    e.preventDefault();
    setErrorMsg("");
    setSuccessMsg("");

    if (!email || !password || !passwordConfirm) {
      setErrorMsg("Por favor completa correo y contraseñas.");
      return;
    }

    if (password !== passwordConfirm) {
      setErrorMsg("Las contraseñas no coinciden.");
      return;
    }

    try {
      setIsSubmitting(true);

      if (role === "deportista") {
        // Validaciones básicas
        if (!depNombre || !depApellido || !depDocumento || !depTelefono) {
          setErrorMsg("Completa todos los campos del deportista.");
          setIsSubmitting(false);
          return;
        }

        const payload = {
          email,
          password,
          password_confirm: passwordConfirm,
          nombre: depNombre,
          apellido: depApellido,
          documento_identidad: depDocumento,
          telefono: depTelefono,
        };

        await api.post("/api/accounts/deportistas/", payload);
        setSuccessMsg("Registro de deportista exitoso. Ahora puedes iniciar sesión.");
      } else {
        // role === "club"
        if (
          !clubNombre ||
          !clubNit ||
          !clubDireccion ||
          !clubTel1 ||
          !clubDepartamento ||
          !clubCiudad
        ) {
          setErrorMsg("Completa al menos los campos obligatorios del club (*).");
          setIsSubmitting(false);
          return;
        }

        const payload = {
          email,
          password,
          password_confirm: passwordConfirm,
          nombre: clubNombre,
          nit: clubNit,
          direccion: clubDireccion,
          telefono_1: clubTel1,
          telefono_2: clubTel2 || "",
          departamento: Number(clubDepartamento),
          ciudad: Number(clubCiudad),
          disponibilidad: clubDisponibilidad || "",
          informacion: clubInformacion || "",
        };

        await api.post("/api/accounts/clubes/", payload);
        setSuccessMsg("Registro de club exitoso. Ahora puedes iniciar sesión.");
      }

      // Redirigir al login después de unos segundos
      setTimeout(() => {
        navigate("/login");
      }, 1500);
    } catch (err) {
      console.error(err);
      // Intenta leer error del backend
      const detail =
        err?.response?.data?.detail ||
        err?.response?.data?.error ||
        "Error al registrarse. Verifica los datos.";
      setErrorMsg(detail);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 flex items-center justify-center px-4">
      <div className="max-w-6xl w-full flex flex-col lg:flex-row bg-slate-900/60 rounded-3xl shadow-2xl overflow-hidden border border-slate-700">
        {/* Izquierda */}
        <div className="lg:w-1/2 p-10 flex flex-col justify-between bg-gradient-to-br from-emerald-500/10 via-slate-900 to-slate-900">
          <div className="flex items-center gap-3 mb-8">
            <img src={logo} alt="CanchaYa" className="h-10" />
            <span className="text-emerald-400 font-semibold text-lg">
              CanchaYa
            </span>
          </div>

          <div className="space-y-4">
            <h1 className="text-3xl lg:text-4xl font-bold text-white">
              Crea tu cuenta
            </h1>
            <p className="text-slate-300">
              Regístrate como deportista para reservar canchas o como
              administrador para gestionar tu club.
            </p>

            {/* Selector de rol */}
            <div className="mt-4 inline-flex bg-slate-800/80 rounded-full p-1">
              <button
                type="button"
                onClick={() => setRole("deportista")}
                className={`flex items-center gap-2 px-4 py-2 text-sm rounded-full transition ${
                  role === "deportista"
                    ? "bg-emerald-500 text-slate-900 font-semibold shadow"
                    : "text-slate-300 hover:bg-slate-700/80"
                }`}
              >
                <img src={sportIcon} alt="Deportista" className="w-5 h-5" />
                Deportista
              </button>
              <button
                type="button"
                onClick={() => setRole("club")}
                className={`flex items-center gap-2 px-4 py-2 text-sm rounded-full transition ${
                  role === "club"
                    ? "bg-emerald-500 text-slate-900 font-semibold shadow"
                    : "text-slate-300 hover:bg-slate-700/80"
                }`}
              >
                <img src={adminIcon} alt="Administrador" className="w-5 h-5" />
                Administrador de club
              </button>
            </div>
          </div>

          <div className="mt-10">
            <img
              src={heroImg}
              alt="Ilustración"
              className="w-full max-w-md mx-auto drop-shadow-2xl"
            />
          </div>
        </div>

        {/* Derecha: formulario */}
        <div className="lg:w-1/2 bg-white p-10">
          {/* Volver */}
          <Link
            to="/"
            className="inline-flex items-center gap-2 text-slate-600 text-sm mb-6 hover:text-slate-900"
          >
            <span className="text-lg">←</span>
            Volver al inicio
          </Link>

          <h2 className="text-2xl font-bold text-slate-900 mb-2">
            Registrarse como {role === "deportista" ? "deportista" : "club"}
          </h2>
          <p className="text-sm text-slate-500 mb-6">
            Completa los campos para crear tu cuenta.
          </p>

          {errorMsg && (
            <div className="mb-4 rounded-xl bg-red-50 border border-red-200 px-4 py-2 text-sm text-red-700">
              {errorMsg}
            </div>
          )}

          {successMsg && (
            <div className="mb-4 rounded-xl bg-emerald-50 border border-emerald-200 px-4 py-2 text-sm text-emerald-700">
              {successMsg}
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-4">
            {/* Email y passwords */}
            <div>
              <label className="block text-sm font-medium text-slate-700">
                Correo electrónico
              </label>
              <input
                type="email"
                className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-slate-700">
                  Contraseña
                </label>
                <input
                  type="password"
                  className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-700">
                  Confirmar contraseña
                </label>
                <input
                  type="password"
                  className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                  value={passwordConfirm}
                  onChange={(e) => setPasswordConfirm(e.target.value)}
                  required
                />
              </div>
            </div>

            {/* Campos específicos según el rol */}
            {role === "deportista" ? (
              <>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-slate-700">
                      Nombre
                    </label>
                    <input
                      type="text"
                      className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                      value={depNombre}
                      onChange={(e) => setDepNombre(e.target.value)}
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700">
                      Apellido
                    </label>
                    <input
                      type="text"
                      className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                      value={depApellido}
                      onChange={(e) => setDepApellido(e.target.value)}
                      required
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-slate-700">
                      Documento de identidad
                    </label>
                    <input
                      type="text"
                      className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                      value={depDocumento}
                      onChange={(e) => setDepDocumento(e.target.value)}
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700">
                      Teléfono
                    </label>
                    <input
                      type="text"
                      className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                      value={depTelefono}
                      onChange={(e) => setDepTelefono(e.target.value)}
                      required
                    />
                  </div>
                </div>
              </>
            ) : (
              <>
                <div>
                  <label className="block text-sm font-medium text-slate-700">
                    Nombre del club
                  </label>
                  <input
                    type="text"
                    className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                    value={clubNombre}
                    onChange={(e) => setClubNombre(e.target.value)}
                    required
                  />
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-slate-700">
                      NIT
                    </label>
                    <input
                      type="text"
                      className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                      value={clubNit}
                      onChange={(e) => setClubNit(e.target.value)}
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700">
                      Dirección
                    </label>
                    <input
                      type="text"
                      className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                      value={clubDireccion}
                      onChange={(e) => setClubDireccion(e.target.value)}
                      required
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-slate-700">
                      Teléfono principal
                    </label>
                    <input
                      type="text"
                      className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                      value={clubTel1}
                      onChange={(e) => setClubTel1(e.target.value)}
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700">
                      Teléfono secundario (opcional)
                    </label>
                    <input
                      type="text"
                      className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                      value={clubTel2}
                      onChange={(e) => setClubTel2(e.target.value)}
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-slate-700">
                      ID Departamento *
                    </label>
                    <input
                      type="number"
                      className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                      value={clubDepartamento}
                      onChange={(e) => setClubDepartamento(e.target.value)}
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700">
                      ID Ciudad *
                    </label>
                    <input
                      type="number"
                      className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                      value={clubCiudad}
                      onChange={(e) => setClubCiudad(e.target.value)}
                      required
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-slate-700">
                    Disponibilidad (texto opcional)
                  </label>
                  <input
                    type="text"
                    className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                    value={clubDisponibilidad}
                    onChange={(e) => setClubDisponibilidad(e.target.value)}
                    placeholder="Ej: Lunes a Domingo 6am - 10pm"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-slate-700">
                    Información del club (opcional)
                  </label>
                  <textarea
                    className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                    rows={3}
                    value={clubInformacion}
                    onChange={(e) => setClubInformacion(e.target.value)}
                    placeholder="Descripción breve del club"
                  />
                </div>
              </>
            )}

            <button
              type="submit"
              disabled={isSubmitting}
              className="w-full mt-2 rounded-xl bg-emerald-500 hover:bg-emerald-600 text-white font-semibold py-2.5 text-sm transition disabled:opacity-60"
            >
              {isSubmitting ? "Registrando..." : "Crear cuenta"}
            </button>

            <p className="text-center text-gray-500 text-sm mt-4">
              ¿Ya tienes cuenta?{" "}
              <Link
                to="/login"
                className="font-semibold text-emerald-600 hover:underline"
              >
                Inicia sesión aquí
              </Link>
            </p>
          </form>
        </div>
      </div>
    </div>
  );
}
